"""Generate project-original vector illustrations and the Animals content catalog."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
DEST = ROOT / "assets" / "objects" / "animals"
DEST.mkdir(parents=True, exist_ok=True)

def eyes(y=128, left=153, right=207):
    return f'<g fill="#293d39"><ellipse cx="{left}" cy="{y}" rx="8" ry="11"/><ellipse cx="{right}" cy="{y}" rx="8" ry="11"/></g><g fill="#fffdf4"><circle cx="{left-2}" cy="{y-3}" r="3"/><circle cx="{right-2}" cy="{y-3}" r="3"/></g>'

def smile(y=158):
    return f'<path d="M166 {y}q14 12 28 0" fill="none" stroke="#895e49" stroke-width="4" stroke-linecap="round"/>'

def body(color, paw="#aa7653"):
    return f'<ellipse cx="180" cy="212" rx="62" ry="63" fill="{color}"/><ellipse cx="146" cy="261" rx="26" ry="15" fill="{paw}"/><ellipse cx="214" cy="261" rx="26" ry="15" fill="{paw}"/>'

def cheeks(y=153):
    return f'<g fill="#e7a599" opacity=".55"><ellipse cx="132" cy="{y}" rx="15" ry="7"/><ellipse cx="228" cy="{y}" rx="15" ry="7"/></g>'

drawings = {}
drawings["cat"] = '<path d="M233 234c72 17 65-62 41-53" fill="none" stroke="#d69763" stroke-width="21" stroke-linecap="round"/>' + body("#e7b477", "#ce945e") + '<path d="m112 105 3-64 55 40h21l56-40 2 66c20 70-23 89-69 89s-89-25-68-89" fill="#e7b477"/><path d="m127 67 27 24-28 12m108-36-27 24 29 12" fill="#d28b77"/><ellipse cx="180" cy="161" rx="38" ry="26" fill="#fff3dd"/>' + eyes() + '<path d="m172 149 8-4 8 4-8 8z" fill="#a66860"/><path d="m114 147-31-5m31 17-30 7m162-19 31-5m-31 17 30 7" stroke="#a77450" stroke-width="3" stroke-linecap="round"/>' + smile(165)
