drawings["bear"] = body("#aa7855", "#865b43") + '<circle cx="127" cy="79" r="29" fill="#aa7855"/><circle cx="233" cy="79" r="29" fill="#aa7855"/><circle cx="127" cy="79" r="16" fill="#d0a47b"/><circle cx="233" cy="79" r="16" fill="#d0a47b"/><ellipse cx="180" cy="137" rx="76" ry="72" fill="#b98761"/>' + eyes(130) + '<ellipse cx="180" cy="169" rx="42" ry="32" fill="#e1bc92"/><path d="M168 156q12-8 24 0c-1 17-22 17-24 0" fill="#293d39"/>' + smile(179)
drawings["lion"] = '<path d="M235 231c53 14 31-47 50-45" fill="none" stroke="#ddb569" stroke-width="13" stroke-linecap="round"/><ellipse cx="289" cy="182" rx="15" ry="19" fill="#ac7549"/>' + body("#e5be75", "#c69754") + '<path d="m180 34 27 14 31-1 10 24 25 14-3 30 15 25-14 24 2 29-27 10-16 24-29-4-24 15-25-15-30 2-12-25-26-12 4-28-14-25 15-24-1-30 26-11 15-23 28 3z" fill="#b57b4e"/><circle cx="180" cy="130" r="65" fill="#f0cc84"/>' + eyes(122) + '<ellipse cx="180" cy="158" rx="39" ry="26" fill="#fff1d1"/><path d="m169 147 11-6 11 6-11 12z" fill="#895d40"/>' + smile(169)
